def cpu_budget():
    """Number of CPUs actually usable (honours cgroup quotas in containers)."""
    try:
        n = len(os.sched_getaffinity(0))
    except Exception:
        n = os.cpu_count() or 1
    quota = None
    try:
        with open("/sys/fs/cgroup/cpu.max") as fh:  # cgroup v2
            parts = fh.read().split()
        if parts and parts[0] != "max":
            quota = float(parts[0]) / float(parts[1])
    except Exception:
        try:  # cgroup v1
            with open("/sys/fs/cgroup/cpu/cpu.cfs_quota_us") as fh:
                q = float(fh.read().strip())
            with open("/sys/fs/cgroup/cpu/cpu.cfs_period_us") as fh:
                per = float(fh.read().strip())
            if q > 0 and per > 0:
                quota = q / per
        except Exception:
            quota = None
    if quota and quota > 0:
        n = min(n, int(max(1, np.floor(quota))))
    return max(1, min(int(n), 8))


